window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 42, "id": "jBm9v87w3aY", "title": "You were caught smoking", "title_zh": "你抽烟被抓到了 (You were caught smoking)", "duration": "00:08:26", "link": "https://www.youtube.com/watch?v=jBm9v87w3aY", "enriched": true, "lines": [{"ts": "00:00:00", "text": "什么叫我怎么来了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "怎么不欢迎主人？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "今天工作不是很忙，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "想着几天没见我的狗狗了，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:00:14", "text": "快来看看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "你好像还有点，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "不太乐意见我的样子。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:00:25", "text": "是怕生什么事了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:28", "text": "小宝贝的。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:32", "text": "刚来找主人，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "小宝贝是怎么了。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:39", "text": "亲一下脸蛋。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "亲亲小嘴。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:46", "text": "躲什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "别动。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:54", "text": "滚下去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "跪着。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "我说刚刚怎么躲着我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "又抽烟是吧？", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:01:13", "text": "好像亲了个见鬼似的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "你就这么惹眼的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "还以为天天跟我抱着、背后耍乖了。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:01:28", "text": "原来一直在撒谎骗我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "低头做什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "头抬起来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:43", "text": "害怕了？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:01:47", "text": "看你胆子挺大的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "来，过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:57", "text": "主人看看这个小嘴。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "怎么就是不老实？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "这几天抽了多少？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "又不说话。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:02:17", "text": "问什么答什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "是想把规矩重学一遍吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:02:27", "text": "现在知道错了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "就非要我抬着你下巴，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "才肯乖乖听话。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:41", "text": "既然学不会做一个乖小朋友，", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:02:46", "text": "那就把你打到听话为止。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:51", "text": "回头我去把这个医院里面拍来的照片，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "全部打印出来，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "在你卧室里面贴满。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:06", "text": "不要。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "现在知道说不要了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "裤子脱了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:03:21", "text": "手撑在床沿。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:23-00:03:26", "text": "屁股撅好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "我没有生气。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "我气得很高。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "我气得是你不爱惜自己。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "所以今天呢，", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:52", "text": "就跟你好好理理规矩，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "长长记性。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "撅好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "腿伸直。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "现在知道哭着求我。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:31", "text": "那你抽烟还撒谎骗我的时候，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:35", "text": "想什么呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:39", "text": "把嘴抿上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "把眼泪收回去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "做错了事情，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "要承担后果，接受惩罚。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:04:53", "text": "敢再多说一句，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:57", "text": "今天惩罚翻倍。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:01", "text": "别动。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:09", "text": "打。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "行了起来吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:21", "text": "好了打完了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "每次罚出来的，", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:30", "text": "都哭个不停。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:34", "text": "又哭了？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:39", "text": "来吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:47", "text": "来主人怀里。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "真的不开心，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:58", "text": "遇到不开心的事情，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "你可以告诉我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "我可以抱着你，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "安慰你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "我们也可以——", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "还可以带你去吃好吃的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:15", "text": "但是你不能每次，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:18", "text": "都用这种方式来发泄情绪。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:21", "text": "对不对？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "主人抱着你不开心吗？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:27", "text": "带你去约会不开心吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:06:30", "text": "所以这也不是借口。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:33", "text": "而且，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:36", "text": "把烟收了，要戒掉，对吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "那就要说到做到。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:42", "text": "以前每遇到主人的时候，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:45", "text": "你直接靠在我身上，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "来宣泄情绪的事情，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "做了也就做了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:55", "text": "可是现在，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:58", "text": "现在不一样了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "有主人陪着你，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:04", "text": "对不对？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:08", "text": "你是只属于主人的小狗狗了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "有心情不好的时候，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "要找主人。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:17", "text": "不能总是一个人在这儿，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "胡思乱想。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "听到了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:27", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:29", "text": "怎么会呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:32", "text": "每次看到头像里，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:35", "text": "你那个小头像一亮，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "我就特别开心。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:07:41", "text": "当然了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:44", "text": "如果再被我发现，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:47", "text": "再有一次，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "上下两个小屁股，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "我就一定罚了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:07:56", "text": "听懂了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:59", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "相信你再也不敢了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "不吓唬你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "但现在，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:12", "text": "作为狗狗，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:14", "text": "被打之后的安慰。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:17", "text": "我去给你放水。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:19", "text": "让你洗个热水澡，这就行了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "好不好？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:08:24", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:24", "text": "一起去。", "speaker": "主人", "tone": "平静", "sound": []}], "scene": "宠物抽烟被抓管娇型。说话者是「主人」，你是他养的「小狗狗」。情境起点：他几天没见你、来看你却发现你躲着抽烟还撒谎，气你不爱惜自己，于是抬起你下巴、脱衣打屁股娇训，罚完把你搂进怀里安抚，说以后不开心就找主人、再犯就真罚，最后放水让你洗个「小盆盆」。整体是「宠物撒谎抽烟被主人惩戒＋事后安抚」型，基调掌控、心疼、甜虐。", "behaviors": [{"desc": "来看几天没见的狗狗，觉你不太乐意见他"}, {"desc": "发现你躲着抽烟，抬起你下巴看小嘴"}, {"desc": "让你脱衣、手撑床，准备打屁股"}, {"desc": "让你腿伸直受罚"}, {"desc": "你哭着求，他让你收回眼泪承担后果"}, {"desc": "动手打你"}, {"desc": "打完后把你搂进怀里安抚"}, {"desc": "放好水让你洗个「小盆盆澡」"}], "tone_summary": "（自动）主人视角独白，语气以平静、命令、询问为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "医疗", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门被推开的时候，她愣了一下，随即有些不自然地往后缩了缩。他拎着东西进门，注意到她躲闪的眼神，语气带着玩味。"}, {"type": "line", "speaker": "主人", "text": "什么叫我怎么来了？怎么不欢迎主人？今天工作不是很忙，想着几天没见我的狗狗了，快来看看。你好像还有点不太乐意见我的样子，是怕生什么事了吗？小宝贝的。刚来找主人，小宝贝是怎么了？"}, {"type": "narr", "text": "他走近，笑着低下头，想亲一下她的脸蛋，又去亲她的嘴。她下意识偏过头，躲了一下。他的动作顿住了，眼神一点点冷下来。"}, {"type": "line", "speaker": "主人", "text": "亲一下脸蛋，亲亲小嘴。躲什么？别动。滚下去，跪着。我说刚刚怎么躲着我——又抽烟是吧？好像亲到了烟味似的。你就这么惹眼的。还以为天天跟我抱着，背地里装乖。原来一直在撒谎骗我。"}, {"type": "narr", "text": "她扑通跪下去，低着头不敢看他。他站在原地，居高临下地看着她，声音带着压着的火气。"}, {"type": "line", "speaker": "主人", "text": "低头做什么？头抬起来。害怕了？看你胆子挺大的。来，过来。主人看看这个小嘴，怎么就是不老实？这几天抽了多少？又不说话。问什么答什么？是想把规矩重学一遍吗？"}, {"type": "narr", "text": "她带着哭腔说，知道错了。他却没有软，伸手抬起她的下巴，逼她看着自己。"}, {"type": "line", "speaker": "主人", "text": "现在知道错了。就非要我抬着你下巴，才肯乖乖听话。既然学不会做一个乖小朋友，那就把你打到听话为止。回头我去把那个医院里拍来的照片，全部打印出来，在你卧室里面贴满。"}, {"type": "narr", "text": "她一听，猛地摇头，说不要。他冷笑了一声，语气却带着不容商量的意思。"}, {"type": "line", "speaker": "主人", "text": "现在知道说不要了。裤子脱了。手撑在床沿。屁股撅好。我没有生气。我气得恨，气得是你不爱惜自己。所以今天呢，就跟你好好理理规矩，长长记性。"}, {"type": "narr", "text": "她咬着唇，慢慢脱掉裤子，手撑在床沿，把脸埋进臂弯里。他站在她身后，声音沉下来。"}, {"type": "line", "speaker": "主人", "text": "撅好。腿伸直。现在知道哭着求我？那你抽烟还撒谎骗我的时候，想什么呢？把嘴抿上，把眼泪收回去。做错了事情，要承担后果，接受惩罚。敢再多说一句，今天惩罚翻倍。别动。打。"}, {"type": "narr", "text": "巴掌一下一下落下来，她咬着牙一声不吭，眼泪却啪嗒啪嗒往下掉。打到后来，他终于停手，语气带着一点无奈的心疼。"}, {"type": "line", "speaker": "主人", "text": "行了，起来吧。好了，打完了。每次罚出来的，都哭个不停。又哭了？来吧，来主人怀里。真的不开心，遇到不开心的事情，你可以告诉我。我可以抱着你，安慰你。我们也可以——还可以带你去吃好吃的。但是你不能每次，都用这种方式来发泄情绪。对不对？"}, {"type": "narr", "text": "她靠进他怀里，哭得一抽一抽的。他轻轻拍着她的背，声音软下来，带着纵容的认真。"}, {"type": "line", "speaker": "主人", "text": "主人抱着你不开心吗？带你去约会不开心吗？所以这也不是借口。而且，把烟收了，要戒掉，对吧？那就要说到做到。以前每遇到主人的时候，你直接靠在我身上，来宣泄情绪的事情，做了也就做了。可是现在不一样了，有主人陪着你，对不对？你是只属于主人的小狗狗了。"}, {"type": "narr", "text": "她在他怀里点头，声音闷闷的。他低头看着她，语气带着郑重的承诺。"}, {"type": "line", "speaker": "主人", "text": "有心情不好的时候，要找主人。不能总是一个人在这儿，胡思乱想。听到了吗？好。怎么会呢？每次看到头像里，你那个小头像一亮，我就特别开心。当然了。如果再被我发现，再有一次，上下两个小屁股，我就一定罚了。听懂了吗？好。相信你再也不敢了。不吓唬你。"}, {"type": "narr", "text": "她破涕为笑，又往他怀里蹭了蹭。他失笑，把人抱起来，语气轻快起来。"}, {"type": "line", "speaker": "主人", "text": "但现在，作为狗狗，被打之后的安慰。我去给你放水，让你洗个热水澡，这就行了。好不好？好，一起去。"}, {"type": "narr", "text": "浴室里水汽氤氲，她窝在热水里，后知后觉地发现——他说一起，还真的一起。烟雾散尽，烟盒被收走了，可那个温暖的怀抱，还在。她知道，有些坏习惯要戒掉，但有些依赖，可以一直留着。"}]}, {"no": 43, "id": "NAiY-j8kCaU", "title": "You were punished by your master for speeding", "title_zh": "你因为超速被主人惩罚了 (You were punished by your master for speeding)", "duration": "00:08:57", "link": "https://www.youtube.com/watch?v=NAiY-j8kCaU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "不过你这个时间应该来得及。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "不许开快车，听到没。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:10-00:00:10", "text": "嗯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "注意安全。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "去吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "大概到公司了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "路上不堵车。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "那你安心工作。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "哥哥晚上给你做好吃的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "回来了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:03", "text": "干嘛，吓着你了？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:06", "text": "我回来这么早。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "不是说过给我家小宝贝做好吃的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:11", "text": "怎么你也早下班？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "没有啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "那是在家附近谈业务。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "也没有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "那你五点下班，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "你五点半就到家了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:26-00:01:28", "text": "嗯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "你懂什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34-00:01:34", "text": "哦！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "下次再也不干了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "这些话你说过多少次了，我都听够了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "每次犯错就一副可怜巴巴的样子。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:46", "text": "还有新鲜的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:49", "text": "你什么你啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:55", "text": "过来我现在不打你。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:58", "text": "你过来我给你聊聊。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:02", "text": "为什么还怕？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:09", "text": "我是看到这板子就害怕。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:12", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "哥哥打你从来都不是目的，对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "任何时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "哥哥都是要保护你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "所以你应该害怕的不是哥哥手里的板子，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:29", "text": "而是你这样一旦出现意外所带来的后果。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "我问你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "从下班到你进家门，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "包括你停车上下楼，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "你一共花了三十分钟。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "所以你车速开了多快？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "回答我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "说话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "我今天早上怎么说的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "对我说下雨天你要慢一点。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "你是怎么答应我的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:03:12", "text": "我接你那是我说你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "但是今天雨越下越大。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "真的是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "要真出了事，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "是想让我后悔，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "后悔当初没有管好你是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "说话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:38", "text": "眼泪收回去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "又没有什么急事，为什么要开这么快。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:03:47", "text": "追剧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "回家就为了追剧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "所以安全都不顾。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "你真的是可以啊，小朋友。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "现在知道怕这板子，跪下了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:11", "text": "知道错了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "还有什么想说的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "种种的犯法。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "还有呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:04:27", "text": "五十下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "以后不会让自己处于危险了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "是吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "也不会让哥哥担心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:41", "text": "乖。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:44", "text": "五十下太多了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "既然宝贝知道错了，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:50", "text": "我们就罚二十下吧。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:53", "text": "要表达一下。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "但是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "这二十下，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "可能会打得比较重一些。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:05", "text": "裤子脱掉。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:08", "text": "不准躲。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:10", "text": "也不准哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:13", "text": "我也不希望听到你恨自己的声音。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "我会让你明白，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "让你好好想一下，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:22", "text": "为了追个破电视剧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "挨这二十下，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:28", "text": "到底是值，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:31", "text": "还是不值。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "懂了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:37", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:40", "text": "那我们开始。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "为什么打你？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:48-00:05:48", "text": "嗯。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "以后怎么做。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "从今天起，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "每天回家的时间，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "合理安排。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "不准磨磨唧唧地，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:27", "text": "很晚了还在追剧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "晚上不睡早上不起。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "路上赶时间。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:37", "text": "听到了没。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "再有一次，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "我就把你捆起来，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:47", "text": "绑到阳台上打，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "绝不留情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "听到了没。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:57", "text": "好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:59", "text": "哭吧。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:02", "text": "现在可以哭了。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:05", "text": "哥哥不是生气了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:07", "text": "哥哥是心疼，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:09", "text": "也是担心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "明白吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:13", "text": "哥哥从来没有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:15", "text": "因为生气打过你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:18", "text": "哥哥知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "你以后肯定是不会了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:22", "text": "这个小屁股，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:24", "text": "看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:26", "text": "怕这一个星期，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:28", "text": "坐起来都会痛啊！", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:31", "text": "哥哥今天很凶啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:34", "text": "还不许哭。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:37", "text": "哥哥只是希望，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "不要每次犯错，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "都因为惊吓害怕而逃避。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:07:46", "text": "是希望你们真的，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "明白自己犯这个错误，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:52", "text": "而且明白下次要怎么做。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:59", "text": "嗯，好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "下次不让宝贝憋着眼泪了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:06", "text": "今天呢，", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:08:08", "text": "是真的很担心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "其实早上我看到，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:12", "text": "你跟我说到公司的时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:14", "text": "那个时间我就知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:16", "text": "你一定开得很快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:18", "text": "上次。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:22", "text": "上次和这次情况不一样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:24", "text": "不代表我在鼓励你开快车。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:27", "text": "相信你的技术和判断，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:30", "text": "你开得快是两码事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:33", "text": "明白就好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:36", "text": "好在哥哥怀里，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:38-00:08:40", "text": "抱一会儿。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "你肉肉的，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:44", "text": "怎么也瘦成这样？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "下次乖一点，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:47", "text": "我们就不用来这儿了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "哥哥也不用这么心疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:08:47", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:08:47", "text": "听话就好。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:08:47", "text": "哥哥永远都护着你。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "超速被哥哥惩罚型。说话者是「哥哥／抱抱」，你是下班开快车赶回家追剧的「宝贝」。情境起点：他今早叮嘱下雨慢开，你却为追剧五点半就到家、仅用三十分钟，他算出门道后既心疼又罚，把五十下减成二十下重打、脱裤挨板子，再抱你安抚说「哥哥是担心不是生气」。整体是「危险驾驶被管娇＋惩罚后温柔抱慰」型，基调紧张、掌控、甜。", "behaviors": [{"desc": "叮嘱你出门不许开快车、注意安全"}, {"desc": "回来发现你早下班、五点半就到家，起疑"}, {"desc": "说哥哥打你不是目的，是要你怕出事的后果"}, {"desc": "让你去板子前跪下认错"}, {"desc": "说原定五十下、减成二十下重打，让你脱裤"}, {"desc": "罚完问你为什么打、以后怎么做"}, {"desc": "说现在可以哭了，哥哥是心疼担心"}, {"desc": "看你小屁股、说这一周坐起来都会痛"}, {"desc": "抱你一会儿，说哥哥永远护着你"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、温柔为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "职场", "家庭/长辈", "治愈", "敏感"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": ["捆", "绑", "跪下"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "早上，他送她到门口，雨还在下。他看了一眼时间，语气带着不放心的叮嘱。她点头应着，钻进车里。"}, {"type": "line", "speaker": "哥哥", "text": "不过你这个时间应该来得及。不许开快车，听到没。嗯。快，注意安全，去吧。大概到公司了？路上不堵车？好，那你安心工作，哥哥晚上给你做好吃的。"}, {"type": "narr", "text": "傍晚，门锁转动。他系着围裙从厨房探出头，就看见她站在玄关，心虚地低着头。他放下锅铲，走过来，语气带着了然。"}, {"type": "line", "speaker": "哥哥", "text": "回来了？干嘛，吓着你了？我回来这么早，不是说过给我家小宝贝做好吃的吗？怎么你也早下班？没有啊！那是在家附近谈业务？也没有。那你五点下班，五点半就到家了。嗯？你懂什么？哦！下次再也不干了？这些话你说过多少次了，我都听够了。"}, {"type": "narr", "text": "她低着头，绞着手指。他看着她，语气带着压着的火气，却先没有发作。"}, {"type": "line", "speaker": "哥哥", "text": "每次犯错就一副可怜巴巴的样子，还有新鲜的吗？你什么你啊！过来。过来我现在不打你，你过来我给你聊聊。为什么还怕？我是看到这板子就害怕。爸爸。哥哥打你从来都不是目的，对吧？任何时候，哥哥都是要保护你。"}, {"type": "narr", "text": "她眼圈红红的，小声嗯了一声。他看着她，语气认真起来。"}, {"type": "line", "speaker": "哥哥", "text": "所以你应该害怕的不是哥哥手里的板子，而是你这样一旦出现意外所带来的后果。我问你，从下班到你进家门，包括你停车上下楼，你一共花了三十分钟。所以你车速开了多快？回答我。说话。我今天早上怎么说的？对我说下雨天你要慢一点。你是怎么答应我的？"}, {"type": "narr", "text": "她低着头，声音越来越小。他看着她，语气带着后怕的心疼。"}, {"type": "line", "speaker": "哥哥", "text": "我接你那是我说你。但是今天雨越下越大，真的是。要真出了事，是想让我后悔，后悔当初没有管好你是不是？说话。不准哭，眼泪收回去。又没有什么急事，为什么要开这么快。追剧？回家就为了追剧，所以安全都不顾。你真的是可以啊，小朋友。"}, {"type": "narr", "text": "她跪下去，眼泪在眼眶里打转，却忍着没有掉。他看着她，语气终于缓了一分。"}, {"type": "line", "speaker": "哥哥", "text": "现在知道怕这板子，跪下了。知道错了。还有什么想说的。种种的犯法。还有呢？五十下。以后不会让自己处于危险了，是吧？也不会让哥哥担心。乖。五十下太多了？既然宝贝知道错了，我们就罚二十下吧。要表达一下。但是，这二十下，可能会打得比较重一些。"}, {"type": "narr", "text": "她趴好，咬着唇。他举起板子，语气带着认真的告诫。"}, {"type": "line", "speaker": "哥哥", "text": "裤子脱掉，不准躲，也不准哭，我也不希望听到你恨自己的声音。我会让你明白，让你好好想一下，为了追个破电视剧，挨这二十下，到底是值，还是不值。懂了吗？好，那我们开始。说，为什么打你？嗯。以后怎么做。好。"}, {"type": "narr", "text": "二十下打完，她趴在原地，眼泪终于没忍住。他放下板子，语气彻底软下来，带着心疼。"}, {"type": "line", "speaker": "哥哥", "text": "从今天起，每天回家的时间合理安排，不准磨磨唧唧的，很晚了还在追剧，晚上不睡早上不起，路上赶时间。听到了没。再有一次，我就把你捆起来，绑到阳台上打，绝不留情。听到了没？好了，哭吧，现在可以哭了。哥哥不是生气了，哥哥是心疼，也是担心，明白吗？"}, {"type": "narr", "text": "她哭得一抽一抽的。他把她捞进怀里，一下一下拍着她的背。"}, {"type": "line", "speaker": "哥哥", "text": "哥哥从来没有因为生气打过你。哥哥知道，你以后肯定是不会了。这个小屁股，看看，怕是这一个星期，坐起来都会痛啊！哥哥今天很凶啊！还不许哭。哥哥只是希望，不要每次犯错，都因为惊吓害怕而逃避。是希望你们真的，明白自己犯这个错误，而且明白下次要怎么做。好吧？嗯，好，下次不让宝贝憋着眼泪了。"}, {"type": "narr", "text": "她靠在他怀里，小声说知道了。他低头亲了亲她的发顶，语气带着释然的心疼。"}, {"type": "line", "speaker": "哥哥", "text": "今天呢，是真的很担心。其实早上我看到，你跟我说到公司的时候，那个时间我就知道，你一定开得很快。上次？上次和这次情况不一样，不代表我在鼓励你开快车。相信你的技术和判断，你开得快是两码事。明白就好。好在哥哥怀里，抱一会儿。你肉肉的，怎么也瘦成这样？"}, {"type": "narr", "text": "她靠在他怀里，抽噎着渐渐平静下来。他轻轻拍着她的背，声音温柔。"}, {"type": "line", "speaker": "哥哥", "text": "下次乖一点，我们就不用来这儿了，哥哥也不用这么心疼，好不好？听话就好。哥哥永远都护着你。"}, {"type": "narr", "text": "窗外雨声渐小。她靠在他怀里，听着他一下一下的心跳。挨了二十下，也听了一整晚的心疼——她知道，比起那顿板子，他更怕的，是她出事。而那句“哥哥永远都护着你”，比什么都暖。"}]}, {"no": 44, "id": "jYIxSrq-HgU", "title": "Your boyfriend comforts you who are not ideal in the exam", "title_zh": "男友安抚考得不理想的你 (Your boyfriend comforts you who are not ideal in the exam)", "duration": "00:04:41", "link": "https://www.youtube.com/watch?v=jYIxSrq-HgU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "不怕。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:00:05", "text": "我在这儿呢。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:10", "text": "过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:15", "text": "能不能，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "别总是抽泣。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "看着小鼻子冻得都有点红了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "手伸过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:33", "text": "给你暖暖。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "手这么凉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:39", "text": "今天怎么下课这么晚。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "同学们都走了，你们班其他同学早就出来了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "跟我说实话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "没有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "觉得你今天有点闷闷不乐的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "发生什么事了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "我哪有过不问清楚就罚你的时候。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:01:00-00:01:03", "text": "不害怕。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:06", "text": "是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "考试成绩不理想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "还有呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:01:19", "text": "这就别细想了。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:20", "text": "哎呦。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:23", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:28-00:01:30", "text": "不难过。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "一次考试嘛！", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:01:35", "text": "别灰心。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:38", "text": "哥哥知道，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "宝贝付出了特别的努力。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:43", "text": "之前你每天晚上都复习到这么晚，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "然后中途也不肯离开书桌，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "有几次累到在桌子上睡着了，", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:51", "text": "都是我把你抱回床上的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "爸爸。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "太疼。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:02:00", "text": "这个考试吧，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "它有偶然性。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "有时候咱们付出了很多努力，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "它就不一定达到理想的结果。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "那咱不能因为，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:10", "text": "一次考试，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "考得有点糟糕，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "咱们就失去信心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "小事情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "以后会变好的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "所以，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "不会这样下去了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:28", "text": "你说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "罚你。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:33", "text": "罚你是因为呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:35", "text": "这次你主动说出来，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "然后，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "你想想，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "这次罚你不是因为没考好，", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:02:43", "text": "是你骗我，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "一直说成绩没有公布。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "然后再上次，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "你还是骗我，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "偷偷自己改成绩，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "被哥哥发现之后教训一顿。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "还有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "没让他看见的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:01", "text": "不让我说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "罚过就算过去了。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:03:07", "text": "你那个卷子呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:10", "text": "拿给我看看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "怎么这纸揉成一团？天哪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "小孩子一样，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "不开心就把卷子团起来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:22", "text": "我这小宝贝最会闹脾气了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "他其实还是软软的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "好了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "给你把安全带系好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "扣住。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "走。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "带你去吃点好吃的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "当然了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "因为你这次，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "虽然没有考好，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "但是又诚实，", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:05", "text": "对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "然后表现又好。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:08", "text": "实际上我的小宝贝只是脑袋瓜子笨了点。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:10", "text": "所以要吃点好吃的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:14", "text": "但是不要高兴太早。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "一会儿吃饱回家，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "我可是要检查作业的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "没有作业？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "做我布置的作业，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "就是，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "上次教你的词汇，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "有没有好好学会？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "走吧。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "考试失利安慰型。说话者是「哥哥／抱抱」，你是考得不理想、还因骗他说成绩没公布而被揭穿的「宝贝」。情境起点：他看你鼻子冻红、手凉，问出你考试失利又撒谎改过成绩，先点明「罚你是因为骗我」，再温柔说一次考试不算什么、夸你努力，最后系好安全带带你去吃好吃的、回家检查作业。整体是「犯错被揭穿后的包容安慰」型，基调温柔、宠溺、治愈。", "behaviors": [{"desc": "让你过来，看你小鼻子冻得有点红"}, {"desc": "让你手伸过来暖一暖，问为何下课这么晚"}, {"desc": "说你复习到深夜累趴桌上睡着、还抱你回床"}, {"desc": "点明罚你是因为骗他、偷偷改成绩"}, {"desc": "看你把卷子团成一团，说小孩子一样"}, {"desc": "给你系好安全带"}, {"desc": "带你去吃好吃的，说考不好但诚实就好"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、责备为主，题材偏校园/师生。", "genre_tags": ["校园/师生", "家庭/长辈"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "校门口的人群渐渐散去，他还站在原地。直到那个熟悉的身影低着头走出来，他才迎上去，张开手臂。"}, {"type": "line", "speaker": "哥哥", "text": "不怕。我在这儿呢。过来。"}, {"type": "narr", "text": "她扑进他怀里，肩膀轻轻抽动。他低头看她，发现她鼻尖红红的，显然哭过了。他心口一紧，却先笑了。"}, {"type": "line", "speaker": "哥哥", "text": "能不能，别总是抽泣。看着小鼻子冻得都有点红了。手伸过来，给你暖暖。手这么凉。"}, {"type": "narr", "text": "他握住她冰凉的手，拢在掌心里捂着，一边低头看她。她不敢抬头，睫毛上还挂着泪。"}, {"type": "line", "speaker": "哥哥", "text": "今天怎么下课这么晚？同学们都走了，你们班其他同学早就出来了？"}, {"type": "narr", "text": "她摇头，小声说没有。他轻轻叹了口气，没有戳破她，只是把人往怀里带了带。"}, {"type": "line", "speaker": "哥哥", "text": "跟我说实话。没有？觉得你今天有点闷闷不乐的。发生什么事了？"}, {"type": "narr", "text": "她把脸埋进他胸口，闷了许久，才小声说出来——考试成绩不理想。他低头，亲了亲她的发顶，语气没有半点责怪。"}, {"type": "line", "speaker": "哥哥", "text": "我哪有过不问清楚就罚你的时候。不害怕。是，考试成绩不理想。还有呢？"}, {"type": "narr", "text": "她摇头，说没有了。他揉了揉她的头发，语气温柔。"}, {"type": "line", "speaker": "哥哥", "text": "这就别细想了。哎呦。哥哥。爸爸。哥哥。爸爸。不难过。一次考试嘛！别灰心。"}, {"type": "line", "speaker": "哥哥", "text": "哥哥知道，宝贝付出了特别的努力。之前你每天晚上都复习到这么晚，然后中途也不肯离开书桌。有几次累到在桌子上睡着了，都是我把你抱回床上的。"}, {"type": "narr", "text": "她在他怀里摇头，声音闷闷的——可是还是没考好。他捧起她的脸，替她擦掉眼泪，语气认真。"}, {"type": "line", "speaker": "哥哥", "text": "爸爸。太疼。这个考试吧，它有偶然性。有时候咱们付出了很多努力，它就不一定达到理想的结果。"}, {"type": "narr", "text": "她抬头看他，眼眶红红的。他揉了揉她的头发，声音放轻。"}, {"type": "line", "speaker": "哥哥", "text": "那咱不能因为，一次考试，考得有点糟糕，咱们就失去信心。对吧？小事情。以后会变好的。"}, {"type": "narr", "text": "她靠在他怀里，慢慢不哭了。他低头看着她，忽然话锋一转，语气带上了点无奈。"}, {"type": "line", "speaker": "哥哥", "text": "所以，不会这样下去了，好不好？你说。罚你。罚你是因为呢？"}, {"type": "narr", "text": "她身体一僵，心虚地低下头。他叹了口气，语气却没有多严厉，更多是操心。"}, {"type": "line", "speaker": "哥哥", "text": "这次你主动说出来，然后，你想想，这次罚你不是因为没考好，是你骗我，一直说成绩没有公布。对吧？"}, {"type": "narr", "text": "她小声嗯了一声。他继续说，语气越来越无奈。"}, {"type": "line", "speaker": "哥哥", "text": "然后再上次，你还是骗我，偷偷自己改成绩，被哥哥发现之后教训一顿。还有，没让他看见的。不让我说。罚过就算过去了。"}, {"type": "line", "speaker": "哥哥", "text": "你那个卷子呢？拿给我看看。怎么这纸揉成一团？天哪。小孩子一样，不开心就把卷子团起来。我这小宝贝最会闹脾气了。"}, {"type": "narr", "text": "她从书包里摸出皱巴巴的卷子，心虚地递给他。他接过来，小心地展开，看到分数，没有多说什么，只是叹了口气。"}, {"type": "line", "speaker": "哥哥", "text": "他其实还是软软的。好了。给你把安全带系好。扣住。走。带你去吃点好吃的。"}, {"type": "narr", "text": "他拉开车门，替她把安全带扣好，动作仔细。她坐在副驾上，偷偷看他，小声问，还生气吗。"}, {"type": "line", "speaker": "哥哥", "text": "当然了，因为你这次，虽然没有考好，但是又诚实，对吧？然后表现又好。实际上我的小宝贝只是脑袋瓜子笨了点。所以要吃点好吃的。好不好？"}, {"type": "narr", "text": "她被他那句“脑袋瓜子笨了点”说得又气又好笑，脸一下子鼓起来。他看着她，眼底全是笑意。"}, {"type": "line", "speaker": "哥哥", "text": "但是不要高兴太早。一会儿吃饱回家，我可是要检查作业的。没有作业？做我布置的作业，就是，上次教你的词汇，有没有好好学会？"}, {"type": "narr", "text": "她小声说，学会了。他发动车子，侧头看她一眼，语气带着宠溺。"}, {"type": "line", "speaker": "哥哥", "text": "走吧。"}, {"type": "narr", "text": "车子缓缓驶出校门，路灯一盏一盏掠过车窗。她靠在椅背上，侧头看着他专注开车的侧脸，忽然觉得，考砸了好像也没那么可怕了。"}]}, {"no": 45, "id": "Ja-PZgAw6DM", "title": "Your boyfriend punishes you for self mutilation", "title_zh": "男友因你自残而惩罚你 (Your boyfriend punishes you for self mutilation)", "duration": "00:08:06", "link": "https://www.youtube.com/watch?v=Ja-PZgAw6DM", "enriched": true, "lines": [{"ts": "00:00:00", "text": "宝贝。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:00:03", "text": "宝贝你在里面吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:06", "text": "别关门了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "吓着了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "怎么还害羞呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:14", "text": "快来让爸爸抱。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "想好了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:19-00:00:29", "text": "还想让爸爸抱。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "想好了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:34", "text": "对呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:00:37", "text": "忙完了就回来得比较早。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "我感觉已经不太对。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "平时你不是从小就让我早点回家陪你吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:46", "text": "怎么今天看到我之后慌慌张张的？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "是背着我做什么了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:52", "text": "比如，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "不是其他的小哥哥。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "你和哥哥都想念主人。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "偷偷干坏事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "我不懂，不懂你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "你手后藏着什么？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "到底怎么了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "你伸出来让我看看。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "快点，别让我重复。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:25", "text": "你这搞不清是怎么回事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "有人在学校欺负你了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "没有。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "自己弄的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "为什么不跟我说？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "我有没有，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "我有没有说过，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "无论什么事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "都不准伤害自己。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:53", "text": "说过是吧？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:57", "text": "好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "今天就收拾你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "等着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "不是喜欢伤害自己吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:02:14", "text": "我来帮你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:17", "text": "伤口怕着凉，", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:20", "text": "得养好长时间。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "疼就怎么了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:30", "text": "原来还知道疼啊！", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:32", "text": "往那儿趴好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "手放到前面。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "我要是发现你的手，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "敢往后挡一下，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:43", "text": "我就不罚了，", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:02:46", "text": "也不再管你了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "你想做什么我也不拦着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "想试你就试。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "我让你动了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:02:59", "text": "疼。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:03", "text": "你做这些事的时候，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "怎么一点不觉得疼？", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:11", "text": "看来我平时做得太轻了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "也要像你这样，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "留下这种痕迹，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:20", "text": "你才能觉得怕。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:23", "text": "既然想不明白，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "就罚到你清醒为止。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:03:40", "text": "站起来干什么？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:42", "text": "接着趴好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "我数三下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "站回原位。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "一。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "二。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "三。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "现在连我的话都不听了是吧？", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:04:02", "text": "趴好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "是真的知道错了，还是因为疼。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:04:17", "text": "自己说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "还敢不敢有下次。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "过来跪着。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:36", "text": "好好说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "都哪错了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "伤害自己的事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "我不想再看到你做第二次，听到没。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "你听好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "犯别的错，", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:54", "text": "小惩大诫一下就过去了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "但今天这种错，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "绝对不会轻易放过你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "控制不住，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "就让你牢牢记住这个教训。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "知道了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:05:15", "text": "好了好了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "哭成这个样子。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:05:19", "text": "起来吧。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:21", "text": "刚刚没问原因就罚你，", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:05:24", "text": "因为你做的事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "本身就让我很生气。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "无论因为什么都不可以。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:33", "text": "现在。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:35", "text": "来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "和哥哥说说，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "到底怎么了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "好，不着急，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "慢慢说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "过来过来抱抱。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:54", "text": "来，过来抱。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:58", "text": "来，过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:02", "text": "再怎样都不能做傻事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "坏情绪没地方发泄，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:06", "text": "也不可以发泄到自己身上。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:08", "text": "这太不值了，对不对？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "想想，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "最后事情也没解决，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:15", "text": "然后咱把自己弄得满身都是伤。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "你觉得这样，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "这样合适吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:23", "text": "如果有难过、心情糟糕的时候，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "可以告诉我呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:28", "text": "你知道我一定会，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "陪你一起解决的。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:06:32", "text": "你知道的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "好不好？", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:06:37", "text": "好，抱住。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "亲你一下额头。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "那宝宝一直都特别棒，", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:06:50", "text": "不要不自信。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "无论发生什么事情，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "哥哥永远在你身边。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:59", "text": "来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:02", "text": "把你圈在怀里。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "哥哥再看一下伤口。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:12", "text": "疼不疼啊！", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:07:18-00:07:26", "text": "别动。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:38", "text": "给你包好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "让这里再涂一下，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:54", "text": "这样应该会好得更快一些。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:00", "text": "觉得累了就在怀里靠一会儿吧。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:08:00", "text": "闭上眼睛，什么都不用想。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:00", "text": "干嘛？", "speaker": "爸爸", "tone": "撒娇", "sound": []}], "scene": "自残被惩罚管娇型。说话者是「抱抱／哥哥」，你因情绪低落自己弄伤了身体。情境起点：他回家发现你慌张、逼你伸出手看到伤口，怒而说「无论何事都不准伤害自己」，把你趴好、跪着严厉惩戒，又心疼地抱你、上药、让你靠怀里闭眼休息。整体是「自伤被恋人发现后的震怒与温柔疗愈」型，基调沉重、心疼、极度宠护。", "behaviors": [{"desc": "敲门让你出来，说让抱抱抱"}, {"desc": "发现你见他就慌张、像背着他做坏事"}, {"desc": "让你伸出来看手上的自伤痕迹"}, {"desc": "说无论什么事都不准伤害自己"}, {"desc": "让你趴好、手放前面受罚"}, {"desc": "罚完让你过来跪着认错"}, {"desc": "抱住你、摸摸头安抚"}, {"desc": "把你圈在怀里说永远在你身边"}, {"desc": "别动，给你伤口上药"}, {"desc": "让你靠怀里闭眼什么都不想、烤一会儿"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、命令、温柔为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "家庭/长辈", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门锁转动的声音响起，比平时早了很多。她正坐在床边发呆，听见动静猛地站起来，慌乱地把手藏到身后。他推门进来，一眼就看见她这副心虚的样子，脚步顿了顿。"}, {"type": "line", "speaker": "哥哥", "text": "宝贝，你在里面吗？别关门了。吓着了？怎么还害羞呢？快来让爸爸抱。想好了吗？还想让爸爸抱？想好了吗？对呀！忙完了就回来得比较早。"}, {"type": "narr", "text": "她站在原地，不敢上前。他走过去，语气带着一点怀疑的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "我感觉已经不太对。平时你不是从小就让我早点回家陪你吗？怎么今天看到我之后，慌慌张张的？是背着我做什么了吗？比如，不是其他的小哥哥——你和哥哥都想瞒着主人，偷偷干坏事，是不是？我不懂你。你手后藏着什么？到底怎么了。你伸出来让我看看。快点，别让我重复。"}, {"type": "narr", "text": "她咬着唇，慢慢把手伸出来。手背上、手腕上，几道触目惊心的划痕。他的眼神一下子沉下来，声音却平静得反常。"}, {"type": "line", "speaker": "哥哥", "text": "你这搞不清是怎么回事。有人在学校欺负你了？没有？自己弄的。为什么不跟我说？我有没有，我有没有说过，无论什么事情，都不准伤害自己。说过是吧？好。今天就收拾你。等着。不是喜欢伤害自己吗？我来帮你。伤口怕着凉，得养好长时间。"}, {"type": "narr", "text": "她站在那里，眼泪在眼眶里打转。他指了指床边，语气带着不容违抗的冷。"}, {"type": "line", "speaker": "哥哥", "text": "疼就怎么了？原来还知道疼啊！往那儿趴好。手放到前面。我要是发现你的手敢往后挡一下，我就不罚了，也不再管你了。你想做什么，我也不拦着。想试你就试。我让你动了吗？疼？你做这些事的时候，怎么一点不觉得疼？"}, {"type": "narr", "text": "巴掌一下一下落下来，她咬着唇，一声不吭，眼泪却啪嗒啪嗒往下掉。他听着她压抑的哭声，语气却依然冷硬。"}, {"type": "line", "speaker": "哥哥", "text": "看来我平时做得太轻了，是不是？也要像你这样，留下这种痕迹，你才能觉得怕。既然想不明白，就罚到你清醒为止。站起来干什么？接着趴好。我数三下，站回原位。一，二，三。现在连我的话都不听了是吧？趴好。"}, {"type": "narr", "text": "她重新趴好，哭得上气不接下气。他看着她，语气终于缓了一分，却依然带着分量。"}, {"type": "line", "speaker": "哥哥", "text": "是真的知道错了，还是因为疼。自己说。还敢不敢有下次。过来，跪着，好好说。都哪错了。伤害自己的事情，我不想再看到你做第二次，听到没。你听好，犯别的错，小惩大诫一下就过去了。但今天这种错，绝对不会轻易放过你。控制不住，就让你牢牢记住这个教训。知道了吗？"}, {"type": "narr", "text": "她跪在那里，抽噎着点头。他看着她哭花的小脸，终于叹了口气，伸手把人拉起来，语气软下来。"}, {"type": "line", "speaker": "哥哥", "text": "好了好了，哭成这个样子，起来吧。刚刚没问原因就罚你，因为你做的事情，本身就让我很生气。无论因为什么都不可以。现在，来，和哥哥说说，到底怎么了。好，不着急，慢慢说。过来过来抱抱。来，过来抱。来，过来。"}, {"type": "narr", "text": "她扑进他怀里，把脸埋进他胸口，眼泪终于决堤。他轻轻拍着她的背，声音带着心疼的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "再怎样都不能做傻事。坏情绪没地方发泄，也不可以发泄到自己身上。这太不值了，对不对？想想，最后事情也没解决，然后咱把自己弄得满身都是伤。你觉得这样，合适吗？如果有难过、心情糟糕的时候，可以告诉我呀！你知道我一定会，陪你一起解决的。你知道的，好不好？"}, {"type": "narr", "text": "她在他怀里，闷闷地应了一声。他低头，在她额角落下一个吻，语气带着郑重的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "好，抱住。亲你一下额头。那宝宝一直都特别棒，不要不自信。无论发生什么事情，哥哥永远在你身边。来，把你圈在怀里。"}, {"type": "narr", "text": "他低头，轻轻托起她受伤的手，仔细查看那几道划痕。她的指尖缩了缩，被他稳稳握住。"}, {"type": "line", "speaker": "哥哥", "text": "哥哥再看一下伤口。疼不疼啊？别动，给你包好。这里再涂一下，这样应该会好得更快一些。觉得累了，就在怀里靠一会儿吧。闭上眼睛，什么都不用想。干嘛？嗯，不哭，哥哥在呢。"}, {"type": "narr", "text": "她靠在他怀里，闭上眼睛，呼吸渐渐平稳。他低头看着她安静的睡颜，又看了一眼她手背上新缠好的纱布，轻轻叹了口气。这双小手，以后他得好好看住了。而那句“无论发生什么事情，哥哥永远在你身边”，他会用一辈子来兑现。"}]}, {"no": 46, "id": "LzeCX73utC8", "title": "Your two-way love with your frigid teacher", "title_zh": "你和冷淡老师的双向恋情 (Your two-way love with your frigid teacher)", "duration": "00:06:02", "link": "https://www.youtube.com/watch?v=LzeCX73utC8", "enriched": true, "lines": [{"ts": "00:00:00", "text": "那是死路。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "你要走到哪儿去啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "天啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:30-00:00:41", "text": "沉默死了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:47-00:00:54", "text": "喂。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "你也醒醒。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "先喝点水。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "这一边。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "你不应该把那酒都喝完的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "英国人的酒量非常好的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "我去看看这附近有没有什么民宿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "你在这儿等我一下。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "我马上回来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "我不会消失的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "你都替我喝这么多酒了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "你要再喝点水吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:02:04", "text": "会不会闹？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "我在这。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "你哪里有没有不舒服，需要什么东西。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "在这儿我能做到的，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:17", "text": "我都会尽量去做。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "我会努力看看的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "什么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "这件事，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "我已经在做了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "是啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "吃个早饭回去吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "这里只有粥和鸡蛋。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "走回去一下可以吧？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "如果胃不舒服就告诉我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "不要像昨天一样，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "人到最后都喝到断片。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "头还好吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:54", "text": "对。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "可能你不记得了吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "这让人失望。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "再睡一会儿吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "大不了再教你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "昨天，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "真的，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "谢谢你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:30-00:06:00", "text": "谢谢你。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "醉酒被老师照顾型（双向暗恋）。说话者是「老师／他」，你是喝醉后迷糊、被他一路照顾的你。情境起点：你差点走进死路、醉得不行，他给你喝水、去找民宿让你等、次日陪你吃粥和鸡蛋的早饭，你断断续续只会说「谢谢你」。整体是「清醒温柔的守护者照顾醉意恋人」型，基调含蓄、克制、暗涌的双向爱意。", "behaviors": [{"desc": "见你往死路走，惊讶喊住你"}, {"desc": "给你喝水、让你缓一缓"}, {"desc": "说去找附近民宿、让你原地等他"}, {"desc": "再问你要不要喝水、有无不舒服"}, {"desc": "说吃个早饭回去吧"}, {"desc": "只有粥和鸡蛋，问你凑合行不行"}, {"desc": "让你再睡一会，说待会叫你"}, {"desc": "你连声说「谢谢你」"}], "tone_summary": "（自动）他视角独白，语气以平静、询问为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "霓虹在车窗外拖成模糊的光带。她替他挡了太多酒，此刻靠在副驾上，头一点一点地往下垂。他偏头看她，忽然伸手扳过方向盘，避开了一条死路，声音里带着无奈。"}, {"type": "line", "speaker": "他", "text": "那是死路。你要走到哪儿去啊！"}, {"type": "narr", "text": "车停稳，他熄了火，侧过身看她。她醉得厉害，连眼皮都抬不动，整个人软在座椅里。他看了她很久，才轻轻开口。"}, {"type": "line", "speaker": "他", "text": "我……天啊。"}, {"type": "narr", "text": "车内安静得只有她浅浅的呼吸声。他垂着眼，半天没动，最后把外套脱下来搭在她身上，声音闷闷的。"}, {"type": "line", "speaker": "他", "text": "沉默死了。喂，你也醒醒。来，先喝点水。"}, {"type": "narr", "text": "他拧开瓶盖，托着她的后脑喂她喝水，她皱着眉咽下去，又往他那边蹭了蹭。他喉结动了动，别开眼。"}, {"type": "line", "speaker": "他", "text": "这一边。你不应该把那酒都喝完的。英国人的酒量非常好的。"}, {"type": "narr", "text": "他扶她坐好，下车环顾四周，又弯腰探进车窗，语气带着商量的意味。"}, {"type": "line", "speaker": "他", "text": "我去看看这附近有没有什么民宿。你在这儿等我一下。我马上回来。我不会消失的。"}, {"type": "narr", "text": "他说到做到，果然很快回来了，手里还多了一碗热粥和几个鸡蛋。她把脸埋进臂弯里，声音含含糊糊的。他听着，脚步顿了一下，把东西放在桌上，语气放软。"}, {"type": "line", "speaker": "他", "text": "你都替我喝这么多酒了。你要再喝点水吗？会不会闹？我在这。你哪里有没有不舒服，需要什么东西。在这儿我能做到的，我都会尽量去做。我会努力看看的。"}, {"type": "narr", "text": "清晨的光从窗帘缝里漏进来。她揉着胀痛的额角醒来，一睁眼就看见他坐在床边的椅子上，手里捧着粥，像等了一夜。"}, {"type": "line", "speaker": "他", "text": "什么？这件事，我已经在做了。好，是啊！吃个早饭回去吧。这里只有粥和鸡蛋。走回去一下可以吧？"}, {"type": "narr", "text": "她小口小口喝着粥，他坐在对面，看她喝得差不多了，才开口，声音很平，却带着一丝不易察觉的紧张。"}, {"type": "line", "speaker": "他", "text": "如果胃不舒服就告诉我。不要像昨天一样，人到最后都喝到断片。头还好吗？对。"}, {"type": "narr", "text": "她放下碗，努力回想昨晚的事，却只记得一片空白。她有些愧疚地低下头。他看了她几秒，忽然轻轻笑了一下。"}, {"type": "line", "speaker": "他", "text": "可能你不记得了吧。这让人失望。再睡一会儿吧。大不了再教你。"}, {"type": "narr", "text": "她一愣，抬头看他。晨光落在他侧脸上，他垂着眼，声音低下去，却一字一句，说得很认真。"}, {"type": "line", "speaker": "他", "text": "昨天，真的，谢谢你了。谢谢你。"}]}, {"no": 47, "id": "GWQdn-_q-VE", "title": "You’re the best thing that ever happened to me（Master's comforting you in the night）", "title_zh": "你是我生命中最美好的事（深夜主人的安抚） (You're the best thing that ever happened to me（Master's comforting you in the night）)", "duration": "00:07:41", "link": "https://www.youtube.com/watch?v=GWQdn-_q-VE", "enriched": true, "lines": [{"ts": "00:00:00", "text": "不过怎么突然跑过来了？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:06", "text": "没事的没有打扰我。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:00:12", "text": "工作差不多做完了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "过来过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:00:24", "text": "到怀里来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "我今天好乖。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:00:33", "text": "终于记得要穿拖鞋了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "看来前几天爱撒娇。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:39", "text": "让你长记性了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "是不是？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "我不管。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "你不管。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "但是你刚刚不是答应过哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "要陪哥哥睡觉的吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:00:57", "text": "怎么才这么一会儿就想我了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:00", "text": "像只小猫咪一样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "一直下去吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "那我也能让你歇下吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:08", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "你一下热热。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "很多。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "看你怎么那样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "做我想的事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "把你搂在怀里。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "怎么不躲了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "我的小猫咪。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:01:40", "text": "抱起来软软的。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:44", "text": "好可爱。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "头发和身上。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "也都是像线的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "那是什么？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "你知道世界上最幸福的是什么吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:06", "text": "就是现在这样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "当我抱着你的时候。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "那些你抱的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "比我还要紧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "你总说我给你足够的安全感。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "其实。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "你也让我特别爱惜。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:35", "text": "有时候会想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "和宝贝在一起时间这么长了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:02:42", "text": "为什么这个小家伙？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "一直都在毫无保留地爱着我呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:49", "text": "我就真的让你喜欢吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:53", "text": "真的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "但我有时候也会想。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:06", "text": "我的宝宝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:03:09", "text": "是经历了多少事。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:12", "text": "说了多少回才。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "变成现在这样。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "这么软。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "这么温柔的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:24", "text": "好好好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "不说了不说了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "不说了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "别看我的小可爱。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:36", "text": "小小的一团。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "来表演猫猫的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "可谁能知道。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "内心其实是一个特别坚强的小女孩。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:49", "text": "对啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "在我这里。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "你永远都是一个小女孩。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "而且你也不用一直这么坚强。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "宝贝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:04:04", "text": "哥哥会保护你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "我会把所有的爱和温柔都给你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "因为。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "你是上天赐给我的。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:17", "text": "最好的礼物。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "礼物。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "小哭包眼睛怎么又红了？", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:26", "text": "每次想跟你说这个心里话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:29", "text": "就看你眼圈的时候。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "把这抱着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "没事。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:38", "text": "我在这儿。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:41-00:04:44", "text": "再哭。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:04:47", "text": "不要掉眼泪了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "不然明天眼睛又该肿了。", "speaker": "哥哥", "tone": "责备", "sound": []}, {"ts": "00:04:53", "text": "不听话是不是？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:01", "text": "不听话的话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:09", "text": "我就只好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "不听话。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:25", "text": "只有这样才能让你停下来对吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "小小。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:33", "text": "可以发泄一下情绪。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "但是哥哥就是狠心的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "看到你的眼泪就是不忍心。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "不听话宝宝。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:48", "text": "小小的时候才最好看的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "你也想黏着。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "对啊这样才可爱吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:05:57", "text": "那你看。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:00", "text": "现在时间不早了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:03", "text": "我漂漂亮亮的小宝贝是不是该和哥哥乖乖去睡觉了。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:07", "text": "好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "我帮你回去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:27", "text": "过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:29", "text": "靠过来点。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:32", "text": "靠过来。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:35", "text": "这什么姿势啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:38", "text": "你这样睡脖子会痛的快躺好。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:06:41", "text": "快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:44", "text": "要被子盖好。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "明天周末可以多睡一会。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "明天早上呢？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:51", "text": "我做早餐给宝贝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:53", "text": "好不好？", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:56", "text": "不可以。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:06:58", "text": "周末也不能赖在床上。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "早餐必须要吃。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:03", "text": "听到了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:07:05", "text": "这才乖。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:07", "text": "那对。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:10", "text": "小脑袋子靠过来一点。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:07:12", "text": "这让哥哥乖得疼无话可说吧。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:14", "text": "听着心跳。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:17", "text": "哥哥会一直抱着你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:22-00:07:25", "text": "我很宝贝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:28", "text": "这让哥哥乖得疼无话可说吧。", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:07:31", "text": "听着心跳。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:34", "text": "哥哥会一直抱着你的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:07:37-00:07:37", "text": "我很宝贝。", "speaker": "哥哥", "tone": "撒娇", "sound": []}], "scene": "小猫咪夜晚撒娇型。说话者是「哥哥」，你是被唤作「小猫咪／小宝贝」的你。情境起点：你半夜跑来找他、他抱你进怀，蹭着他撒娇、你抱得比他还紧，他心疼你眼红、不许你掉泪怕明天眼睛肿，最后帮你躺好、让你靠着他听心跳入睡。整体是「深夜黏人小猫撒娇＋温柔哄睡」型，基调极甜、治愈、宠溺。", "behaviors": [{"desc": "让你过来、进他怀里"}, {"desc": "说你终于记得穿拖鞋，夸你长了记性"}, {"desc": "像小猫一样蹭你，把你全抱在怀里"}, {"desc": "说小猫咪软软的、好可爱"}, {"desc": "抱着你，你比他抱得还紧"}, {"desc": "说你是上天最好礼物，见你眼红不让掉泪"}, {"desc": "帮你回床、靠过来躺好别扭脖子"}, {"desc": "让你靠着他听心跳，说周末早餐也要吃"}, {"desc": "说哥哥会一直抱着你"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、撒娇为主，题材偏治愈。", "genre_tags": ["治愈"], "genre_main": "治愈/宠溺", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "深夜，书房的灯还亮着。她轻手轻脚地推开门，探进半个脑袋。他抬头看见她，原本疲惫的眼神一下子软下来，朝她招了招手。"}, {"type": "line", "speaker": "哥哥", "text": "怎么突然跑过来了？没事的，没有打扰我。工作差不多做完了。过来，到怀里来。"}, {"type": "narr", "text": "她走过去，被他轻轻捞进怀里。他低头闻了闻她的发顶，语气带着欣慰的笑意。"}, {"type": "line", "speaker": "哥哥", "text": "我今天好乖，终于记得要穿拖鞋了。看来前几天撒娇，让你长记性了，是不是？"}, {"type": "narr", "text": "她在他怀里蹭了蹭，小声嘟囔了一句。他失笑，把人圈得更紧了些。"}, {"type": "line", "speaker": "哥哥", "text": "我不管，你不管。但是你刚刚不是答应过哥哥，要陪哥哥睡觉的吗？怎么才这么一会儿就想我了？像只小猫咪一样，一直赖下去吧。"}, {"type": "narr", "text": "她埋在他胸口不肯抬头，闷闷地说，那你也要陪我。他低头，在她发顶落下一个吻。"}, {"type": "line", "speaker": "哥哥", "text": "那我也能让你歇下吧。好。你一下热热的，很多。看你怎么那样。做我想的事——把你搂在怀里，怎么不躲了？我的小猫咪。"}, {"type": "narr", "text": "她靠在他怀里，整个人放松下来。他的手指穿过她的发丝，一下一下，声音带着困意里藏不住的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "抱起来软软的，好可爱。头发和身上，也都是香香的。那是什么？你知道世界上最幸福的是什么吗？就是现在这样，当我抱着你的时候。"}, {"type": "narr", "text": "她轻轻嗯了一声，把脸埋得更深。他望着怀里的她，声音带着一点感慨。"}, {"type": "line", "speaker": "哥哥", "text": "那些你抱的，比我还要紧。你总说我给你足够的安全感。其实，你也让我特别爱惜。有时候会想，和宝贝在一起时间这么长了，为什么这个小家伙，一直都在毫无保留地爱着我呢？我就真的让你喜欢吗？"}, {"type": "narr", "text": "她在他怀里点头，声音闷闷的——真的。他低头，指尖轻轻蹭过她的脸颊。"}, {"type": "line", "speaker": "哥哥", "text": "真的。但我有时候也会想，我的宝宝，是经历了多少事，伤了多少回，才变成现在这样。这么软，这么温柔的。好好好，不说了不说了，别又勾起你的小情绪。"}, {"type": "narr", "text": "他揉了揉她的头发，没有继续往下说。她却在他怀里红了眼眶，紧紧攥住他的衣角。"}, {"type": "line", "speaker": "哥哥", "text": "别看我的小可爱，小小的一团，来表演猫猫的。可谁能知道，内心其实是一个特别坚强的小女孩。对啊！在我这里，你永远都是一个小女孩。而且你也不用一直这么坚强。"}, {"type": "narr", "text": "他的声音低下来，一字一字，像是怕惊碎什么。她靠在他胸口，听着他一下一下的心跳。"}, {"type": "line", "speaker": "哥哥", "text": "宝贝，哥哥会保护你的。我会把所有的爱和温柔都给你。因为，你是上天赐给我的，最好的礼物。"}, {"type": "narr", "text": "她抬起头，眼睛果然已经红了。他哭笑不得，伸手捧住她的脸，语气带着故意的严肃。"}, {"type": "line", "speaker": "哥哥", "text": "小哭包，眼睛怎么又红了？每次想跟你说这些心里话，就看到你眼圈泛红。把这抱着，没事，我在这儿。再哭，不要掉眼泪了，不然明天眼睛又该肿了。不听话是不是？"}, {"type": "narr", "text": "她吸了吸鼻子，努力把眼泪憋回去。他看着她倔强的模样，声音放得更软。"}, {"type": "line", "speaker": "哥哥", "text": "不听话的话，我就只好……不听话，只有这样才能让你停下来，对吧？小小，可以发泄一下情绪。但是哥哥就是狠不下心，看到你的眼泪就是不忍心。"}, {"type": "narr", "text": "他低头，轻轻吻了吻她的眼角。她整个人一颤，眼泪却终于停住了。"}, {"type": "line", "speaker": "哥哥", "text": "不听话的宝宝，小小的时候才最好看。你也想黏着？对啊，这样才可爱嘛。那你看，现在时间不早了。我漂漂亮亮的小宝贝，是不是该和哥哥乖乖去睡觉了？"}, {"type": "narr", "text": "她红着脸点了点头。他把她打横抱起来，走向卧室，替她盖好被子，自己也在她身边躺下来。"}, {"type": "line", "speaker": "哥哥", "text": "好。来，我帮你回去。过来，靠过来点。这什么姿势啊？你这样睡，脖子会痛的，快躺好。快，被子盖好。"}, {"type": "narr", "text": "她乖乖躺好，眼睛却一眨不眨地看着他。他失笑，伸手遮住她的眼睛。"}, {"type": "line", "speaker": "哥哥", "text": "明天周末，可以多睡一会儿。明天早上呢？我做早餐给宝贝，好不好？不可以，周末也不能赖在床上。早餐必须要吃，听到了吗？这才乖。"}, {"type": "narr", "text": "她撇了撇嘴，还是乖乖应了一声。他笑了笑，把人往怀里带了带。"}, {"type": "line", "speaker": "哥哥", "text": "小脑袋靠过来一点。这让哥哥乖得，疼得无话可说了。听着心跳，哥哥会一直抱着你的，我的宝贝。"}, {"type": "narr", "text": "她靠在他胸口，听着那一下一下沉稳的心跳，困意一点点漫上来。他低头，在她额角落下一个吻，声音轻得像梦呓。晚安，我的宝贝。这个夜晚，和往后的每一个夜晚，他都会这样抱着她。"}]}, {"no": 48, "id": "YA9DT7GTlgA", "title": "private secretary 2 - Late night parking lot", "title_zh": "私人秘书 2 - 深夜停车场 (private secretary 2 - Late night parking lot)", "duration": "00:10:53", "link": "https://www.youtube.com/watch?v=YA9DT7GTlgA", "enriched": true, "lines": [{"ts": "00:00:00", "text": "在哪儿呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:02", "text": "那过会儿。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:04", "text": "晚上主人带你去吃饭。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "对啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "我回来了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "那差不多几个小时。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "就在哪儿呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:18", "text": "那过会儿。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "晚上主人带你去吃饭。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "对啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "我回来了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:27", "text": "那差不多几个小时。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "那差不多几个小时之后。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "我在地下停车场接你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "好吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "但你其实打扮一些。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "然后。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "今天穿的裙子吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:49", "text": "很好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "那建筑人的手上要求是什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "还记得吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:57", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "还有。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "口罩带好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "哥哥。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "这儿呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:29", "text": "先过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:33", "text": "来我这边。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "主人先检查一下。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:41", "text": "裙子掀起来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:45", "text": "停车场。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "所以你才要快一点。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "这是命令。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "没让你放下来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "转过去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "转回来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "很好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "请你再趴下吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:10", "text": "行。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "请起来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:14-00:02:16", "text": "你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "做得很好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "可以上车了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "想住了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:02:50", "text": "主人也想我的小哥哥。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:02:58", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "给。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "出门的时候给你买的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "项圈呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "带上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "现在好多了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "想令你可以天天守信了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "现在才是一只小哥哥呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:53", "text": "依稀刚才在外面。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "对着那水势力的人掀裙子的样子。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:00", "text": "你知道想什么吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:04", "text": "累得好。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:08", "text": "但是这么害羞一看就是矜持的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "不过。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "主人喜欢。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:20", "text": "当然了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "喜欢你把不为人知一面展现。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:26", "text": "给我的样子吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:29", "text": "特别服从命令。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:32", "text": "而平日不一样的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "都展现给我。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:39", "text": "我的小哥哥越来越知道。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:42", "text": "怎么让主人开心啊？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "挺干净。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "到了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:12", "text": "别急。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:16", "text": "先来吃你的饭前甜点。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:20", "text": "跪在座上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:28", "text": "这么像主人呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:05:33", "text": "别急。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:38", "text": "一口一口吃。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "我过头说汗了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "中卖力的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "别安分了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:50", "text": "真棒。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "不要推下去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "也不准吐出来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:59", "text": "就这样含着。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:02", "text": "呜呜的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "不是说想主人吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:06:08", "text": "那就多感受一下主人的味道。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "你问我这满车。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "也都是哥哥的味道。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "下车。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "您好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:28", "text": "爱走。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "今天吃点什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "我都可以问她吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "今天要吃点什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:36", "text": "对。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:38", "text": "你不能说话。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:40", "text": "还是给我吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:42", "text": "我看看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:44-00:06:54", "text": "（音频转写失真，已压缩）。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:56-00:06:59", "text": "这个。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "真保险。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:04", "text": "然后整个小红瓣。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:06", "text": "现在可以脱下去了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:07:09", "text": "然后上湖帮。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:13", "text": "就张开我检查一下。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:18", "text": "吃个药这么难。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:22", "text": "来给自己点个甜点吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:25", "text": "奖励你的。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:07:28", "text": "今天可以吃。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:33", "text": "那就这些了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:36", "text": "可以了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:39", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:42", "text": "请稍等。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:45", "text": "您好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:46", "text": "晚安。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:48", "text": "爱走。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "这边一共消费。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:51", "text": "一千零五十元。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "老板。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "我先代开了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:57", "text": "帮我记一下。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:58", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:00", "text": "直接刷吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "归之记。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:04", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:07", "text": "感谢您用餐。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "好了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:15", "text": "走吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "都这么累了。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:26", "text": "你要记得咱们车停那儿吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:08:30", "text": "你不是一向都记得的吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:08:34", "text": "我只刚才被主人玩傻了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:39", "text": "可爱的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "这害羞的样子。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "真是怎么看都看不够啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:49", "text": "但是。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:52", "text": "小秘书不细心。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:55", "text": "是不是要罚？", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:08:59", "text": "给我找。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:09:02", "text": "不然你就这么找。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:09:05", "text": "外套给我。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:09:09", "text": "得给我吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:09:18", "text": "马上的风吹得还挺舒服的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:09:21", "text": "会冷吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:09:24", "text": "不冷。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:09:27", "text": "怕歇吧。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:09:31", "text": "怕是去找车。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:09:34", "text": "就这样。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:09:38", "text": "主人就在你身边。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:09:41", "text": "那狗狗秀绝不是都很灵验吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:09:45", "text": "还找不到主人的车吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:09:49", "text": "不容易。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:10:09", "text": "快。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:11", "text": "钻进去吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:14", "text": "对。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:16", "text": "就是后备箱。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:19", "text": "宝贝。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:10:25", "text": "宜宝。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:31", "text": "狗狗做得很好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:37", "text": "还可以吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:10:41", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:49", "text": "绑好了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:10:49", "text": "好好在这里给我带着。", "speaker": "主人", "tone": "命令", "sound": []}], "scene": "秘书／主人 停车场约会扮演（private secretary 2）。说话者是「主人／哥哥」，你是他私秘「小狗狗／小哥哥」。情境起点：深夜他约你在楼下停车场接你，检查你穿裙子、戴口罩，车上戴项圈、喂你「饭前甜点」，再去餐厅点牛肉、检查上菜，最后找回车、夸你乖。整体是「主人带宠物秘书夜间外出调娇」型，基调服从、暧昧、掌控甜。", "behaviors": [{"desc": "约你几小时后在地下停车场接你"}, {"desc": "让你打扮漂亮、戴上口罩"}, {"desc": "主人先检查、让你把裙子撩起来"}, {"desc": "让你转过去、再转回来检查"}, {"desc": "检查合格、让你上车"}, {"desc": "给你戴上出门买的项圈"}, {"desc": "车上让你吃「饭前甜点」、一口口来"}, {"desc": "下车进餐厅，点牛肉"}, {"desc": "上菜后让你张开嘴检查"}, {"desc": "找回车，夸「狗狗做得很好」"}], "tone_summary": "（自动）主人视角独白，语气以平静、询问、命令为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "职场", "治愈", "敏感"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["项圈", "绑"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "电话那头，她的声音带着一点犹豫。他放下手里的文件，语气带着一点不容商量的温柔。"}, {"type": "line", "speaker": "主人", "text": "在哪儿呢？那过会儿，晚上主人带你去吃饭。对啊！我回来了。那差不多几个小时，就在哪儿呢？那过会儿，晚上主人带你去吃饭。对啊！我回来了。那差不多几个小时之后，我在地下停车场接你，好吧？但你打扮一下。好，然后，今天穿的裙子吗？很好。那见主人的要求是什么？还记得吗？好，还有，口罩戴好。哥哥，这儿呢？先过来，来我这边，主人先检查一下。"}, {"type": "narr", "text": "她走到他面前，低着头。他看着她，语气带着一点认真的打量。"}, {"type": "line", "speaker": "主人", "text": "裙子掀起来？停车场。所以你才要快一点，这是命令，没让你放下来。转过去，转回来，很好。请你再趴下吧，行，请起来。你做得很好，可以上车了。好，想主人了吗？主人也想我的小哥哥。好，给，出门的时候给你买的。项圈呢？带上。好，现在好多了。想让你可以天天戴着。现在才是一只小哥哥呢？依稀刚才在外面，对着那些水势利的人的样子，你知道想什么吗？累得好。但是这么害羞，一看就是矜持的。不过，主人喜欢。"}, {"type": "narr", "text": "她靠进副驾，小声说了句谢谢。他发动车子，语气带着一点满意的温柔。"}, {"type": "line", "speaker": "主人", "text": "当然了，喜欢你把不为人知的一面，展现给我的样子。特别服从命令，和平日不一样，都展现给我。我的小哥哥越来越知道，怎么让主人开心了。挺干净。来，到了，别急，先来吃你的饭前甜点，跪在座上，这么想主人呢？别急，一口一口吃。我过头说汗了，这么卖力，别咽了。真棒，不要推下去，也不准吐出来，就这样含着，呜呜的。不是说想主人吗？那就多感受一下主人的味道。你问我这满车，也都是哥哥的味道。"}, {"type": "narr", "text": "她红着脸，含着那东西，靠进椅背。他看着她，语气带着一点满足的笑意。"}, {"type": "line", "speaker": "主人", "text": "下车，您好，爱走，今天吃点什么？我都可以问她吧？今天要吃点什么？对，你不能说话，还是给我吧，我看看，这个，真保险，然后整个小红瓣，现在可以脱下去了，然后上湖帮，就张开我检查一下。吃个药这么难？来，给自己点个甜点吧，奖励你的，今天可以吃。好，那就这些了，可以了。好，请稍等。您好，晚安，爱走，这边一共消费一千零五十元。老板，我先代开了，帮我记一下，好，直接刷吧，归之记，好，感谢您用餐。好了，走吧。"}, {"type": "narr", "text": "她跟在他身后走出餐厅，低头系着围巾。他回头看她，语气带着一点促狭的温柔。"}, {"type": "line", "speaker": "主人", "text": "都这么累了？你要记得咱们车停哪儿吗？你不是一向都记得的吗？我，刚才被主人玩傻了。可爱的，这害羞的样子，真是怎么看都看不够啊！但是，小秘书不细心，是不是要罚？给我找，不然你就这么找。外套给我，得给我吧。马上的风吹得还挺舒服的。会冷吗？不冷？怕歇吧，怕是去找车，就这样，主人就在你身边。那狗狗的嗅觉不是都很灵吗？还找不到主人的车吗？不容易，快，钻进去吧。对，就是后备箱。宝贝，宜宝。狗狗做得很好。还可以吗？好，绑好了，好好在这里给我带着。"}, {"type": "narr", "text": "车灯亮起，他发动车子。后备箱里传来她闷闷的声音。他笑了笑，声音透过车厢传来，带着一点纵容的温柔。这一夜的“惩罚”，其实从始至终，都只是他想多陪她一会儿的借口。而他答应过她的——到家，就解开。"}]}]);